package review.mysql;
import ai_study_planner.*;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

/** Runs against memory H2 offline, or the separately approved dedicated MySQL. No HTTP listener needed. */
public final class DualLedgerScenario {
 public final DualLedgerDiagnostics diagnostics; public final ConfigurableApplicationContext ctx;public final String id;public final DualLedgerRuntime.Fixture fixture;public final DualLedgerRuntime.Wire wire;public final MockMvc mvc;public MockHttpSession session;public String token;
 public DualLedgerScenario(ConfigurableApplicationContext ctx,String id,DualLedgerRuntime.Fixture f,DualLedgerRuntime.Wire wire,DualLedgerRuntime.Gate gate){this.ctx=ctx;diagnostics=ctx.getBean(DualLedgerDiagnostics.class);this.id=id;fixture=f;this.wire=wire;mvc=MockMvcBuilders.webAppContextSetup((org.springframework.web.context.WebApplicationContext)ctx).addFilters(ctx.getBean("springSecurityFilterChain",jakarta.servlet.Filter.class),gate).build();}
 public static void need(boolean ok,String stage){if(!ok)throw new DualLedgerDiagnostics.Failure(stage,"ASSERTION_FAILED",0,0);}
 public static String key(){return "dual_"+UUID.randomUUID();}
 public static com.fasterxml.jackson.databind.JsonNode tree(MvcResult r)throws Exception{return IntegrationRuntime.JSON.readTree(r.getResponse().getContentAsByteArray());}
 public void login(String password)throws Exception{diagnostics.enter("LOGIN");var r=mvc.perform(get("/auth/csrf")).andReturn();session=(MockHttpSession)r.getRequest().getSession();token=tree(r).path("token").asText();need(mvc.perform(post("/auth/login").session(session).header("X-CSRF-TOKEN",token).param("username",IntegrationSchema.OWNER).param("password",password)).andReturn().getResponse().getStatus()==200,"LOGIN");token=tree(mvc.perform(get("/auth/csrf").session(session)).andReturn()).path("token").asText();}
 public MvcResult write(String path,long goal,String key,Object body)throws Exception{return mvc.perform(post(path).session(session).header("X-CSRF-TOKEN",token).header("X-Integration-Run",id).header("Idempotency-Key",key).param("goalId",""+goal).contentType("application/json").content(IntegrationRuntime.JSON.writeValueAsBytes(body))).andReturn();}
 public MvcResult read(String path,long goal,Map<String,String> extra)throws Exception{var q=get(path).session(session).param("goalId",""+goal);extra.forEach(q::param);return mvc.perform(q).andReturn();}
 public Map<String,Object> log(){return Map.of("userId",1,"subjectId",fixture.subjectA(),"studyDate",fixture.day().minusDays(1).toString(),"studyMinutes",40,"studyContent","[가상 두 원장] 기록","understandingScore",3,"focusScore",3,"fatigueScore",2);}
 public static Map<String,Object> aiBody(){return Map.of("confirmPaidCall",true,"expectedModel",DualLedgerProfile.MODEL);}
 public static void rollbackFailure(StudyLogIdempotencyFailure e,boolean injectionReached){need(e.status==503,"ROLLBACK_STATUS");need(injectionReached,"ROLLBACK_INJECTION_NOT_REACHED");}
 public Map<String,Object> run(String password)throws Exception{
  login(password);var jdbc=ctx.getBean(JdbcTemplate.class);var baseline=DualLedgerRuntime.protectedRows(jdbc,fixture);String study=key(),daily=key(),summary=key();
  diagnostics.enter("FIRST_LOG");var first=write("/study-logs",fixture.goalA(),study,log());diagnostics.expect(first,200,"FIRST_LOG");diagnostics.enter("STUDY_REPLAY");need(tree(first).equals(tree(write("/study-logs",fixture.goalA(),study,log()))),"STUDY_REPLAY");diagnostics.enter("STUDY_CONFLICT");var changed=new HashMap<>(log());changed.put("studyMinutes",41);need(write("/study-logs",fixture.goalA(),study,changed).getResponse().getStatus()==409,"STUDY_CONFLICT");
  diagnostics.enter("CONCURRENT_STUDY");String concurrent=key();var pool=Executors.newFixedThreadPool(2);try{var ready=new CountDownLatch(2);var go=new CountDownLatch(1);Callable<Integer> call=()->{ready.countDown();need(go.await(5,TimeUnit.SECONDS),"CONCURRENT_WAIT");return write("/study-logs",fixture.goalA(),concurrent,log()).getResponse().getStatus();};var a=pool.submit(call);var b=pool.submit(call);need(ready.await(3,TimeUnit.SECONDS),"CONCURRENT_READY");go.countDown();need(a.get()==200&&b.get()==200,"CONCURRENT_STUDY");}finally{pool.shutdownNow();}
  diagnostics.enter("ROLLBACK");long count=ctx.getBean(StudyLogRepository.class).count(),ledger=jdbc.queryForObject("SELECT COUNT(*) FROM study_log_requests",Long.class);
  var injectionReached=new java.util.concurrent.atomic.AtomicBoolean();var failing=new StudyLogIdempotencyService(jdbc,ctx.getBean(StudyLogRepository.class),ctx.getBean(SubjectRepository.class),ctx.getBean(GoalRepository.class),ctx.getBean(org.springframework.transaction.PlatformTransactionManager.class),true){protected void afterPersist(){injectionReached.set(true);throw new IllegalStateException("Synthetic rollback");}};
  var payload=new StudyLog();payload.setUserId(1L);payload.setSubjectId(fixture.subjectA());payload.setStudyDate(fixture.day().minusDays(1));payload.setStudyMinutes(40);payload.setStudyContent("가상 롤백");payload.setFocusScore(3);payload.setUnderstandingScore(3);payload.setFatigueScore(2);
  try{failing.save(1,fixture.goalA(),key(),payload);need(false,"ROLLBACK_NOT_TRIGGERED");}catch(StudyLogIdempotencyFailure expected){rollbackFailure(expected,injectionReached.get());}need(count==ctx.getBean(StudyLogRepository.class).count()&&ledger==jdbc.queryForObject("SELECT COUNT(*) FROM study_log_requests",Long.class),"ROLLBACK_ATOMIC");
  diagnostics.enter("DAILY");var d=write("/llm-coaching",fixture.goalA(),daily,aiBody());diagnostics.expect(d,200,"DAILY");need(tree(d).path("responseSaved").asBoolean(),"DAILY");diagnostics.enter("DAILY_REPLAY");var duplicateDaily=write("/llm-coaching",fixture.goalA(),daily,aiBody());diagnostics.expect(duplicateDaily,200,"DAILY_REPLAY");need(tree(d).equals(tree(duplicateDaily)),"DAILY_REPLAY");need(wire.counts().get("DAILY_COACHING")==1,"NO_DUPLICATE_WIRE");
  diagnostics.enter("SUMMARY");diagnostics.expect(write("/study-log-summary",fixture.goalA(),summary,aiBody()),200,"SUMMARY");need(wire.counts().get("STUDY_SUMMARY")==1,"SUMMARY_WIRE");
  diagnostics.enter("RESPONSE_STORE_FAILURE");var recorder=ctx.getBean(AiResponseRecorder.class);var service=ctx.getBean(AiResponseService.class);var failStore=new AiResponseService(ctx.getBean(AiResponseRepository.class),ctx.getBean(StudyQuestionRepository.class),ctx.getBean(GoalRepository.class)){public AiResponse save(Long goal,AiResponse.Feature f,String requested,String actual,String model,AiResponse.Source source,String text,Boolean complete,StudyQuestion question){throw new IllegalStateException("Synthetic response-store failure");}};
  var dailyController=ctx.getBean(LlmCoachingController.class);try{ReflectionTestUtils.setField(dailyController,"responseRecorder",new AiResponseRecorder(failStore));var r=write("/llm-coaching",fixture.goalA(),key(),aiBody());need(r.getResponse().getStatus()==200&&!tree(r).path("responseSaved").asBoolean()&&tree(r).at("/costProtection/resultStored").asBoolean(),"PAID_RESPONSE_VS_STORE");}finally{ReflectionTestUtils.setField(dailyController,"responseRecorder",recorder);}
  // Discard a committed receipt and recover only through GET. No POST resend is performed here.
  diagnostics.enter("GET_RECOVERY");String lost=key();var committed=write("/study-log-summary",fixture.goalA(),lost,aiBody());need(committed.getResponse().getStatus()==200,"LOST_REPLY_COMMIT");need(tree(read("/ai-generation-requests",fixture.goalA(),Map.of("feature","STUDY_SUMMARY","requestKey",lost))).path("state").asText().equals("COMPLETED"),"GET_RECOVERY");
  diagnostics.enter("SUMMARY_LIMIT");int before=wire.counts().get("STUDY_SUMMARY");need(write("/study-log-summary",fixture.goalA(),key(),aiBody()).getResponse().getStatus()==429&&wire.counts().get("STUDY_SUMMARY")==before,"SUMMARY_LIMIT");
  diagnostics.enter("SERVICE_RECREATION");var old=SecurityContextHolder.getContext();try{var auth=SecurityContextHolder.createEmptyContext();auth.setAuthentication(UsernamePasswordAuthenticationToken.authenticated(IntegrationSchema.OWNER,null,List.of(new SimpleGrantedAuthority("ROLE_DEMO_OWNER"))));SecurityContextHolder.setContext(auth);var fresh=new AiCostProtection(jdbc,ctx.getBean(GoalRepository.class),ctx.getBean(org.springframework.transaction.PlatformTransactionManager.class),ctx.getEnvironment());need(fresh.lookup("DAILY_COACHING",fixture.goalA(),daily).get("state").equals("COMPLETED"),"SERVICE_RECREATION_AI");var freshStudy=new StudyLogIdempotencyService(jdbc,ctx.getBean(StudyLogRepository.class),ctx.getBean(SubjectRepository.class),ctx.getBean(GoalRepository.class),ctx.getBean(org.springframework.transaction.PlatformTransactionManager.class),true);need(IntegrationRuntime.JSON.readTree(freshStudy.lookup(1,fixture.goalA(),study)).path("state").asText().equals("COMPLETED"),"SERVICE_RECREATION_STUDY");}finally{SecurityContextHolder.setContext(old);}
  diagnostics.enter("UNCERTAIN");wire.timeoutNext.set(true);String uncertain=key();var timed=write("/llm-coaching",fixture.goalA(),uncertain,aiBody());need(tree(timed).at("/costProtection/state").asText().equals("UNKNOWN"),"UNCERTAIN");before=wire.counts().get("DAILY_COACHING");need(write("/llm-coaching",fixture.goalA(),key(),aiBody()).getResponse().getStatus()==409&&wire.counts().get("DAILY_COACHING")==before,"NO_UNKNOWN_RETRY");
  diagnostics.enter("CALENDAR");need(read("/study-reschedule-calendar",fixture.goalA(),Map.of("month",java.time.YearMonth.from(fixture.day().minusDays(1)).toString())).getResponse().getStatus()==200,"CALENDAR");diagnostics.enter("RULE_PREVIEW");need(read("/study-reschedule-preview",fixture.goalA(),Map.of()).getResponse().getStatus()==200,"RULE_PREVIEW");diagnostics.enter("PRESERVATION");need(baseline.equals(DualLedgerRuntime.protectedRows(jdbc,fixture)),"FINAL_AND_B_PRESERVED");
  diagnostics.enter("LOGOUT");need(mvc.perform(post("/auth/logout").session(session).header("X-CSRF-TOKEN",token)).andReturn().getResponse().getStatus()==200,"LOGOUT");need(mvc.perform(get("/goals")).andReturn().getResponse().getStatus()==401,"AUTH");
  diagnostics.complete();String backend;try(var c=jdbc.getDataSource().getConnection()){backend=c.getMetaData().getDriverName().contains("H2")?"H2_MEMORY":"MYSQL";}
  return Map.of("mode",DualLedgerProfile.MODE,"serviceRecreationVerified",true,"processRestartVerified",false,"goalBAndFinalPreserved",true,"studyLedgerRows",jdbc.queryForObject("SELECT COUNT(*) FROM study_log_requests",Integer.class),"aiLedgerRows",jdbc.queryForObject("SELECT COUNT(*) FROM ai_generation_requests",Integer.class),"fakeWireCalls",wire.counts(),"realAiCalls",0,"dataBackend",backend);
 }
}
